// Local stand-in for the commercetools auth and API hosts, used to drive the storefront in a browser when no live
// credentials exist (workstreams F and G). Data comes from the seed package (scripts/mock-fixtures/seed-fixtures.json,
// generated by generate.gen.ts): the real category tree, six stores, 41 products with prices, stock and review statistics.
// Served: project, categories, channels, product types, inventory, shipping methods, product projections, Product Search
// (scripts/mock-fixtures/mock-catalog.mjs) and a small cart (create, read, addLineItem). Workstream H added: one projection by id,
// recurrence policies and recurring prices, inventory at one supply channel, supplyChannel and recurrenceInfo on lines,
// placeholder images (MOCK_IMAGES=0 for none) and GET /__mock/carts to read the carts back. Workstream M added reviews
// (list, create, update, delete, statistics kept in step; scripts/mock-fixtures/mock-reviews.mjs) and one demo order.
//
//   node scripts/mock-ct-server.mjs [port]      (needs openssl; writes a throwaway certificate to the OS temp dir)
//   NODE_TLS_REJECT_UNAUTHORIZED=0 CTP_API_URL=https://localhost:9443 CTP_AUTH_URL=https://localhost:9443 \
//     CTP_PROJECT_KEY=mock-project EXPECTED_PROJECT_KEY=mock-project CTP_CLIENT_ID=mock CTP_CLIENT_SECRET=mock \
//     CTP_SCOPES=view_project_settings:mock-project SESSION_SECRET=<32+ chars> npm run dev
//
// With NODE_EXTRA_CA_CERTS=<printed cert path> instead of NODE_TLS_REJECT_UNAUTHORIZED=0 the dev server can still download
// Google fonts (the TLS bypass breaks next/font in dev).
// Nothing here is a real credential. Never point it at a real project.
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync } from 'node:fs';
import { createServer } from 'node:https';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import {
  DOCS, DOC_BY_ID, FIXTURES, RECURRENCE_POLICIES, VARIANT_BY_SKU, categoryId, channelId, priceFor, productTypeResults, projectionOf, runSearch,
} from './mock-fixtures/mock-catalog.mjs';
import { reviewRoutes } from './mock-fixtures/mock-reviews.mjs';

const PORT = Number(process.argv[2] ?? 9443);
const PROJECT = 'mock-project';

const dir = mkdtempSync(join(tmpdir(), 'mock-ct-'));
execFileSync('openssl', [
  'req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-days', '2', '-subj', '/CN=localhost', '-addext', 'subjectAltName=DNS:localhost',
  '-keyout', join(dir, 'key.pem'), '-out', join(dir, 'cert.pem'),
], { stdio: 'ignore' });

const DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
/** Seed hours ("08:00-19:00" or "closed" per day) to the JSON the storefront reads ({day: {open, close} | null}). */
const hoursJson = (hours) =>
  JSON.stringify(Object.fromEntries(DAYS.map((d) => {
    const v = hours[d];
    if (!v || v === 'closed') return [d, null];
    const [open, close] = v.split('-');
    return [d, { open, close }];
  })));

const STORES = FIXTURES.stores.map((s, i) => ({
  id: channelId(i), version: 1, key: s.key, roles: ['InventorySupply'],
  name: { 'en-US': `Malva Coffee ${s.area}`, 'en-CA': `Malva Coffee ${s.area}` },
  address: { country: s.country, state: s.state, city: s.city, postalCode: s.postalCode, streetName: s.street, streetNumber: s.streetNumber },
  geoLocation: { type: 'Point', coordinates: [s.lng, s.lat] },
  custom: {
    type: { typeId: 'type', id: 'mcf-store-type' },
    fields: {
      addressLine: `${s.streetNumber} ${s.street}`, city: s.city, postalCode: s.postalCode, phone: s.phone,
      hours: hoursJson(s.hours), collectionMinutes: s.collectionMinutes,
    },
  },
  createdAt: '2026-01-01T00:00:00.000Z', lastModifiedAt: '2026-01-01T00:00:00.000Z',
}));

const CATEGORIES = FIXTURES.categories.map((c) => ({
  id: categoryId(c.key), version: 1, key: c.key, name: { 'en-US': c.name, 'en-CA': c.name }, slug: { 'en-US': c.slug, 'en-CA': c.slug },
  ...(c.parent ? { parent: { typeId: 'category', id: categoryId(c.parent) } } : {}), orderHint: c.orderHint, ancestors: [],
  createdAt: '2026-01-01T00:00:00.000Z', lastModifiedAt: '2026-01-01T00:00:00.000Z',
}));

const rate = (currency, freeAbove) => ({
  price: { type: 'centPrecision', currencyCode: currency, centAmount: currency === 'USD' ? 695 : 895, fractionDigits: 2 },
  freeAbove: { type: 'centPrecision', currencyCode: currency, centAmount: freeAbove, fractionDigits: 2 },
  isMatching: true,
});

const inventoryEntries = (sku) => {
  const found = VARIANT_BY_SKU.get(sku);
  if (!found) return [];
  const { stock } = found.variant;
  return [
    { id: `inv-${sku}-online`, version: 1, sku, availableQuantity: stock.online, quantityOnStock: stock.online },
    ...stock.stores.map((q, i) => ({
      id: `inv-${sku}-${i}`, version: 1, sku, availableQuantity: q, quantityOnStock: q, supplyChannel: { typeId: 'channel', id: channelId(i) },
    })),
  ];
};


// Customers and login (workstream J). The six seeded demo customers share MOCK_DEMO_PASSWORD (default below, mock only).
const MOCK_DEMO_PASSWORD = process.env.MOCK_DEMO_PASSWORD ?? 'mock-demo-pass-1';
const CUSTOMERS = new Map();
const addCustomer = (email, password, firstName, lastName, extra = {}) => {
  const id = `cust-${CUSTOMERS.size + 1}`;
  const customer = {
    id, version: 1, email, firstName, lastName, isEmailVerified: true, addresses: [], createdAt: '2026-01-01T00:00:00.000Z',
    lastModifiedAt: '2026-01-01T00:00:00.000Z', ...extra,
  };
  CUSTOMERS.set(email.toLowerCase(), { customer, password });
  return customer;
};
[
  ['maya.okonkwo@example.com', 'Maya', 'Okonkwo', { cart: { id: 'cart-maya', units: 1, lines: 1 } }],
  ['liam.carter@example.com', 'Liam', 'Carter'], ['priya.nair@example.com', 'Priya', 'Nair'],
  ['lucas.tremblay@example.com', 'Lucas', 'Tremblay'], ['ava.mackenzie@example.com', 'Ava', 'MacKenzie'],
  ['noah.patel@example.com', 'Noah', 'Patel'],
].forEach(([email, first, last, extra]) => {
  const c = addCustomer(email, MOCK_DEMO_PASSWORD, first, last);
  if (extra?.cart) c.mockCart = extra.cart;
});
const cartBody = (id, units, lines) => ({
  id, version: 1, cartState: 'Active', totalLineItemQuantity: units, lineItems: Array.from({ length: lines }, () => ({ quantity: units / lines })),
});
const readBody = (req) =>
  new Promise((resolve) => {
    let raw = '';
    req.on('data', (c) => (raw += c));
    req.on('end', () => {
      try { resolve(JSON.parse(raw || '{}')); } catch { resolve({}); }
    });
  });
const invalid = (res) => json(res, 400, { statusCode: 400, message: 'Account with the given credentials not found.', errors: [{ code: 'InvalidCredentials' }] });
async function customerRoutes(req, res, path) {
  if (req.method === 'POST' && path === `/${PROJECT}/login`) {
    const body = await readBody(req);
    const entry = CUSTOMERS.get(String(body.email ?? '').toLowerCase());
    if (!entry || entry.password !== body.password) return invalid(res);
    const guest = body.anonymousCart?.id ? CARTS.get(body.anonymousCart.id) : undefined;
    const own = entry.customer.mockCart;
    let cart;
    if (guest && own) {
      cart = cartBody(own.id, own.units + guest.totalLineItemQuantity, own.lines + guest.lineItems.length);
      CARTS.set(own.id, cart); // the merged bag is now the customer's bag
    }
    else if (guest) cart = cartBody(body.anonymousCart.id, guest.totalLineItemQuantity, guest.lineItems.length);
    else if (own) cart = cartBody(own.id, own.units, own.lines);
    return json(res, 200, { customer: entry.customer, ...(cart ? { cart } : {}) });
  }
  if (req.method === 'POST' && path === `/${PROJECT}/customers`) {
    const body = await readBody(req);
    if (CUSTOMERS.has(String(body.email ?? '').toLowerCase())) {
      return json(res, 400, { statusCode: 400, message: 'duplicate', errors: [{ code: 'DuplicateField', field: 'email' }] });
    }
    return json(res, 201, { customer: addCustomer(body.email, body.password, body.firstName, body.lastName) });
  }
  const match = new RegExp(`^/${PROJECT}/customers/([^/]+)$`).exec(path);
  if (req.method === 'GET' && match) {
    const found = [...CUSTOMERS.values()].find((e) => e.customer.id === match[1]);
    return found ? json(res, 200, found.customer) : json(res, 404, { statusCode: 404, message: 'not found' });
  }
  return false;
}
// ---------------------------------------------------------------- carts
const CARTS = new Map([
  ['cart-active', { id: 'cart-active', version: 1, cartState: 'Active', totalLineItemQuantity: 3, lineItems: [{ id: 'li-a', quantity: 2, variant: { sku: 'MCF-POD-EMBER-10' } }, { id: 'li-b', quantity: 1, variant: { sku: 'MCF-POD-CASA-10' } }] }],
]);
CARTS.set('cart-maya', { id: 'cart-maya', version: 1, cartState: 'Active', totalLineItemQuantity: 1, lineItems: [{ id: 'li-m', quantity: 1, variant: { sku: 'MCF-POD-EMBER-10' } }] });
let cartSeq = 0;
const withTotals = (cart) => ({ ...cart, totalLineItemQuantity: cart.lineItems.reduce((n, l) => n + l.quantity, 0) });

function updateCart(cart, body) {
  if (body.version !== cart.version) return { status: 409, body: { statusCode: 409, message: 'Object has a different version', errors: [{ code: 'ConcurrentModification' }] } };
  let next = cart;
  for (const action of body.actions ?? []) {
    if (action.action !== 'addLineItem') return { status: 400, body: { statusCode: 400, message: `unsupported action ${action.action}`, errors: [{ code: 'InvalidOperation', message: 'mock' }] } };
    const found = VARIANT_BY_SKU.get(action.sku);
    if (!found) return { status: 400, body: { statusCode: 400, message: `A product with SKU '${action.sku}' not found.`, errors: [{ code: 'InvalidOperation', message: `A product with SKU '${action.sku}' not found.` }] } };
    if (!priceFor(found.variant, next.country, next.currency ?? next.totalPrice?.currencyCode)) {
      return { status: 400, body: { statusCode: 400, message: 'no price', errors: [{ code: 'MissingPriceForProduct', message: 'no price' }] } };
    }
    // Lines merge on SKU, fulfilment, supply channel and recurrence policy, like the platform (workstream H).
    const sameLine = (l) =>
      l.variant.sku === action.sku && l.custom?.fields?.fulfilment === action.custom?.fields?.fulfilment
      && l.supplyChannel?.id === action.supplyChannel?.id
      && l.recurrenceInfo?.recurrencePolicy?.id === action.recurrenceInfo?.recurrencePolicy?.id;
    const existing = next.lineItems.find(sameLine);
    const price = priceFor(found.variant, next.country, next.currency ?? next.totalPrice?.currencyCode);
    const unit = action.recurrenceInfo ? Math.round(price.cents * 0.9) : price.cents; // the recurring price is 10% below
    next = existing
      ? { ...next, lineItems: next.lineItems.map((l) => (l === existing ? { ...l, quantity: l.quantity + (action.quantity ?? 1) } : l)) }
      : {
          ...next,
          lineItems: [...next.lineItems, {
            id: `li-${next.lineItems.length + 1}-${cartSeq}`, quantity: action.quantity ?? 1, variant: { sku: action.sku }, custom: action.custom,
            price: { value: { currencyCode: price.currency, centAmount: unit } },
            ...(action.supplyChannel ? { supplyChannel: action.supplyChannel } : {}),
            ...(action.recurrenceInfo ? { recurrenceInfo: action.recurrenceInfo } : {}),
          }],
        };
  }
  return { status: 200, body: withTotals({ ...next, version: cart.version + 1 }) };
}

const list = (results, total = results.length) => ({ limit: 500, offset: 0, count: results.length, total, results });
const json = (res, status, body) => {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(body));
};
// (readBody is declared once, above, in the customers section: J and G each added one and the file did not start.)

createServer({ key: readFileSync(join(dir, 'key.pem')), cert: readFileSync(join(dir, 'cert.pem')) }, async (req, res) => {
  const url = new URL(req.url ?? '/', `https://localhost:${PORT}`);
  const path = url.pathname;
  if (path === `/${PROJECT}/login` || path.startsWith(`/${PROJECT}/customers`)) {
    if ((await customerRoutes(req, res, path)) !== false) return;
  }
  // Reviews and the verified-purchase order lookup (workstream M).
  if (path === `/${PROJECT}/reviews` || path.startsWith(`/${PROJECT}/reviews/`) || path === `/${PROJECT}/orders`) {
    if ((await reviewRoutes(req, res, url, path, readBody)) !== false) return;
  }
  if (path === '/oauth/token') {
    return json(res, 200, { access_token: 'mock-token', token_type: 'Bearer', expires_in: 172800, scope: `view_project_settings:${PROJECT}` });
  }
  if (path === `/${PROJECT}`) {
    return json(res, 200, { key: PROJECT, version: 1, countries: ['US', 'CA'], currencies: ['USD', 'CAD'], languages: ['en-US', 'en-CA'] });
  }
  if (path === `/${PROJECT}/channels`) return json(res, 200, list(STORES));
  if (path === `/${PROJECT}/categories`) return json(res, 200, list(CATEGORIES));
  if (path === `/${PROJECT}/product-types`) return json(res, 200, list(productTypeResults()));
  if (path === `/${PROJECT}/shipping-methods/matching-location`) {
    const currency = url.searchParams.get('currency') ?? 'USD';
    const freeAbove = currency === 'CAD' ? 9900 : 7500;
    return json(res, 200, list([
      { id: 'ship-std', version: 1, key: 'mcf-ship-standard', name: 'Standard', zoneRates: [{ zone: { typeId: 'zone', id: 'z' }, shippingRates: [rate(currency, freeAbove)] }] },
    ]));
  }
  if (path === `/${PROJECT}/inventory`) {
    const where = url.searchParams.get('where') ?? '';
    const one = /^sku="([^"]+)"$/.exec(where);
    const many = /^sku in \((.+)\)$/.exec(where);
    // One SKU at one supply channel (the collect check of POST /api/cart/lines, workstream H).
    const atChannel = /^sku="([^"]+)" and supplyChannel\(id="([^"]+)"\)$/.exec(where);
    const skus = one ? [one[1]] : many ? [...many[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]) : atChannel ? [atChannel[1]] : [];
    const entries = skus.flatMap(inventoryEntries);
    return json(res, 200, list(atChannel ? entries.filter((e) => e.supplyChannel?.id === atChannel[2]) : entries));
  }
  // Recurrence policies: the list and one by key (workstream H).
  if (path === `/${PROJECT}/recurrence-policies`) return json(res, 200, list(RECURRENCE_POLICIES));
  const policyMatch = new RegExp(`^/${PROJECT}/recurrence-policies/key=([^/]+)$`).exec(path);
  if (policyMatch) {
    const found = RECURRENCE_POLICIES.find((p) => p.key === decodeURIComponent(policyMatch[1]));
    return found ? json(res, 200, found) : json(res, 404, { statusCode: 404, message: 'not found', errors: [{ code: 'ResourceNotFound' }] });
  }
  // One projection by key (home page) or by id (the product page read).
  const byKey = new RegExp(`^/${PROJECT}/product-projections/key=([^/]+)$`).exec(path);
  const projectionMatch = new RegExp(`^/${PROJECT}/product-projections/([0-9a-f-]{36})$`).exec(path);
  if ((byKey || projectionMatch) && req.method === 'GET') {
    const doc = byKey ? [...DOC_BY_ID.values()].find((d) => d.key === decodeURIComponent(byKey[1])) : DOC_BY_ID.get(projectionMatch[1]);
    if (!doc) return json(res, 404, { statusCode: 404, message: 'not found', errors: [{ code: 'ResourceNotFound' }] });
    return json(res, 200, projectionOf(doc, {
      currency: url.searchParams.get('priceCurrency') ?? undefined,
      country: url.searchParams.get('priceCountry') ?? undefined,
      locales: url.searchParams.getAll('localeProjection'),
    }));
  }
  // Debug read of every cart the mock holds, to check supply channels and recurrence info (not a commercetools route).
  if (path === '/__mock/carts') return json(res, 200, [...CARTS.values()]);
  if (path === `/${PROJECT}/product-projections` && req.method === 'GET') {
    const ids = [
      ...[...(url.searchParams.get('where') ?? '').matchAll(/"([0-9a-f-]{36})"/g)].map((m) => m[1]),
      ...[...url.searchParams].filter(([k]) => /^var\.p\d+$/.test(k)).map(([, v]) => v), // predicate variables (workstream M)
    ];
    const locales = url.searchParams.getAll('localeProjection');
    const currency = url.searchParams.get('priceCurrency') ?? undefined;
    const country = url.searchParams.get('priceCountry') ?? undefined;
    const results = ids.map((id) => DOC_BY_ID.get(id)).filter(Boolean).map((d) => projectionOf(d, { currency, country, locales }));
    return json(res, 200, list(results));
  }
  if (path === `/${PROJECT}/products/search` && req.method === 'POST') {
    try {
      return json(res, 200, runSearch(await readBody(req)));
    } catch (e) {
      return json(res, 400, { statusCode: 400, message: String(e.message), errors: [{ code: 'InvalidInput', message: String(e.message) }] });
    }
  }
  if (path === `/${PROJECT}/carts` && req.method === 'POST') {
    const body = await readBody(req);
    cartSeq += 1;
    const cart = withTotals({
      id: `cart-${cartSeq}`, version: 1, cartState: 'Active', lineItems: [], country: body.country, currency: body.currency,
      totalPrice: { currencyCode: body.currency }, shippingMode: body.shippingMode, ...(body.anonymousId ? { anonymousId: body.anonymousId } : {}),
    });
    CARTS.set(cart.id, cart);
    return json(res, 201, cart);
  }
  const cartMatch = new RegExp(`^/${PROJECT}/carts/([^/]+)$`).exec(path);
  if (cartMatch) {
    const cart = CARTS.get(cartMatch[1]);
    if (!cart) return json(res, 404, { statusCode: 404, message: 'not found' });
    if (req.method === 'POST') {
      const result = updateCart(cart, await readBody(req));
      if (result.status === 200) CARTS.set(cart.id, result.body);
      return json(res, result.status, result.body);
    }
    return json(res, 200, cart);
  }
  console.log(`mock-ct: no fixture for ${req.method} ${path}`);
  return json(res, 404, { statusCode: 404, message: 'No fixture', errors: [{ code: 'ResourceNotFound' }] });
}).listen(PORT, () => console.log(`mock-ct certificate: ${join(dir, 'cert.pem')}\nmock-ct listening on https://localhost:${PORT} (project ${PROJECT}, ${DOCS.length} products)`));
